export function injectIcons() {
  const sym = Object.entries(ICONS).map(([k, v]) => `<symbol id="i-${k}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${v}</symbol>`).join('');
  const emo = Object.entries(EMOTES).map(([k, v]) => `<symbol id="e-${k}" viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round">${v}</symbol>`).join('');
  const div = document.createElement('div');
  div.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" style="position:absolute;width:0;height:0;overflow:hidden" aria-hidden="true">${sym}${emo}</svg>`;
  document.body.prepend(div.firstChild);
}
export const ic = (name, cls = '') => `<svg class="i ${cls}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
export const emote = (name) => `<svg class="emote" aria-hidden="true"><use href="#e-${name}"/></svg>`;
export const hasIcon = (n) => !!ICONS[n];
// Replace :emote: tokens with inline emotes (text must be escaped first)
export function emotify(text) { return text.replace(/:([a-z]+):/g, (m, n) => (EMOTES[n] ? emote(n) : m)); }
export function esc(s) { return String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }
